    76→void adc_hal_arbiter_config(adc_arbiter_t *config)
    77→{
    78→    adc_ll_set_arbiter_work_mode(config->mode);
    79→    adc_ll_set_arbiter_priority(config->rtc_pri, config->dig_pri, config->pwdet_pri);
