    95→void adc_hal_dma_ctx_config(adc_hal_dma_ctx_t *hal, const adc_hal_dma_config_t *config)
    96→{
    97→    hal->desc_dummy_head.next = hal->rx_desc;
    98→    hal->dev = config->dev;
    99→    hal->eof_desc_num = config->eof_desc_num;
   100→    hal->eof_step = config->eof_step;
   101→    hal->dma_chan = config->dma_chan;
   102→    hal->eof_num = config->eof_num;
   103→}
   104→
   105→void adc_hal_digi_init(adc_hal_dma_ctx_t *hal)
   106→{
   107→    // Set internal FSM wait time, fixed value.
   108→    adc_ll_digi_set_fsm_time(ADC_LL_FSM_RSTB_WAIT_DEFAULT, ADC_LL_FSM_START_WAIT_DEFAULT,
   109→                             ADC_LL_FSM_STANDBY_WAIT_DEFAULT);
   110→    adc_ll_set_sample_cycle(ADC_LL_SAMPLE_CYCLE_DEFAULT);
   111→    adc_hal_pwdet_set_cct(ADC_LL_PWDET_CCT_DEFAULT);
   112→    adc_ll_digi_output_invert(ADC_UNIT_1, ADC_LL_DIGI_DATA_INVERT_DEFAULT(ADC_UNIT_1));
   113→    adc_ll_digi_output_invert(ADC_UNIT_2, ADC_LL_DIGI_DATA_INVERT_DEFAULT(ADC_UNIT_2));
   114→    adc_ll_digi_set_clk_div(ADC_LL_DIGI_SAR_CLK_DIV_DEFAULT);
   115→
   116→#if !SOC_GDMA_SUPPORTED
   117→    adc_dma_ll_rx_clear_intr(hal->dev, hal->dma_chan, ADC_HAL_DMA_INTR_MASK);
   118→    adc_dma_ll_rx_enable_intr(hal->dev, hal->dma_chan, ADC_HAL_DMA_INTR_MASK);
   119→#endif /* !SOC_GDMA_SUPPORTED */
   120→    adc_ll_digi_dma_set_eof_num(hal->dev, hal->eof_num);
   121→#if CONFIG_IDF_TARGET_ESP32
   122→    i2s_ll_rx_set_sample_bit(hal->dev, SAMPLE_BITS, SAMPLE_BITS);
   123→    i2s_ll_rx_enable_mono_mode(hal->dev, 1);
   124→    i2s_ll_rx_force_enable_fifo_mod(hal->dev, 1);
   125→    i2s_ll_enable_builtin_adc(hal->dev, 1);
   126→#endif
   127→
   128→    adc_oneshot_ll_disable_all_unit();
   129→}
   130→
   131→void adc_hal_digi_deinit(adc_hal_dma_ctx_t *hal)
   132→{
   133→    adc_ll_digi_trigger_disable(hal->dev);
   134→    adc_ll_digi_dma_disable();
   135→    adc_ll_digi_clear_pattern_table(ADC_UNIT_1);
   136→    adc_ll_digi_clear_pattern_table(ADC_UNIT_2);
   137→    adc_ll_digi_reset(hal->dev);
   138→    adc_ll_digi_controller_clk_disable();
   139→}
