   141→/*---------------------------------------------------------------
   142→                    DMA read
   143→---------------------------------------------------------------*/
   144→static adc_ll_digi_convert_mode_t get_convert_mode(adc_digi_convert_mode_t convert_mode)
   145→{
   146→#if CONFIG_IDF_TARGET_ESP32 || SOC_ADC_DIGI_CONTROLLER_NUM == 1
   147→    return ADC_LL_DIGI_CONV_ONLY_ADC1;
   148→#elif (SOC_ADC_DIGI_CONTROLLER_NUM >= 2)
   149→    switch (convert_mode) {
   150→        case ADC_CONV_SINGLE_UNIT_1:
   151→            return ADC_LL_DIGI_CONV_ONLY_ADC1;
   152→        case ADC_CONV_SINGLE_UNIT_2:
   153→            return ADC_LL_DIGI_CONV_ONLY_ADC2;
   154→        case ADC_CONV_BOTH_UNIT:
   155→            return ADC_LL_DIGI_CONV_BOTH_UNIT;
   156→        case ADC_CONV_ALTER_UNIT:
   157→            return ADC_LL_DIGI_CONV_ALTER_UNIT;
   158→        default:
   159→            abort();
   160→    }
   161→#endif
   162→}
   163→
   164→/**
   165→ * For esp32s2 and later chips
   166→ * - Set ADC digital controller clock division factor. The clock is divided from `APLL` or `APB` clock.
   167→ *   Expression: controller_clk = APLL/APB * (div_num  + div_a / div_b + 1).
   168→ * - Enable clock and select clock source for ADC digital controller.
   169→ * For esp32, use I2S clock
   170→ */
   171→static void adc_hal_digi_sample_freq_config(adc_hal_dma_ctx_t *hal, adc_continuous_clk_src_t clk_src, uint32_t clk_src_freq_hz, uint32_t sample_freq_hz)
   172→{
   173→#if !CONFIG_IDF_TARGET_ESP32
   174→    uint32_t interval = clk_src_freq_hz / (ADC_LL_CLKM_DIV_NUM_DEFAULT + ADC_LL_CLKM_DIV_A_DEFAULT / ADC_LL_CLKM_DIV_B_DEFAULT + 1) / 2 / sample_freq_hz;
   175→    //set sample interval
   176→    adc_ll_digi_set_trigger_interval(interval);
   177→    //Here we set the clock divider factor to make the digital clock to 5M Hz
   178→    adc_ll_digi_controller_clk_div(ADC_LL_CLKM_DIV_NUM_DEFAULT, ADC_LL_CLKM_DIV_B_DEFAULT, ADC_LL_CLKM_DIV_A_DEFAULT);
   179→    adc_ll_digi_clk_sel(clk_src);
   180→#else
   181→    i2s_ll_rx_clk_set_src(hal->dev, I2S_CLK_SRC_DEFAULT);    /*!< Clock from PLL_D2_CLK(160M)*/
   182→    uint32_t bclk_div = 16;
   183→    uint32_t bclk = sample_freq_hz * 2;
   184→    uint32_t mclk = bclk * bclk_div;
   185→    i2s_ll_mclk_div_t mclk_div = {};
   186→    i2s_hal_calc_mclk_precise_division(I2S_BASE_CLK, mclk, &mclk_div);
   187→    i2s_ll_rx_set_mclk(hal->dev, &mclk_div);
   188→    i2s_ll_rx_set_bck_div_num(hal->dev, bclk_div);
   189→#endif
   190→}
   191→
   192→void adc_hal_digi_controller_config(adc_hal_dma_ctx_t *hal, const adc_hal_digi_ctrlr_cfg_t *cfg)
   193→{
   194→#if (SOC_ADC_DIGI_CONTROLLER_NUM == 1)
   195→    //Only one pattern table, this variable is for readability
   196→    const int pattern_both = 0;
   197→
   198→    adc_ll_digi_clear_pattern_table(pattern_both);
   199→    adc_ll_digi_set_pattern_table_len(pattern_both, cfg->adc_pattern_len);
   200→    for (int i = 0; i < cfg->adc_pattern_len; i++) {
   201→        adc_ll_digi_set_pattern_table(pattern_both, i, cfg->adc_pattern[i]);
   202→    }
   203→
   204→#elif (SOC_ADC_DIGI_CONTROLLER_NUM >= 2)
   205→    uint32_t adc1_pattern_idx = 0;
   206→    uint32_t adc2_pattern_idx = 0;
   207→
   208→    adc_ll_digi_clear_pattern_table(ADC_UNIT_1);
   209→    adc_ll_digi_clear_pattern_table(ADC_UNIT_2);
   210→
   211→    for (int i = 0; i < cfg->adc_pattern_len; i++) {
   212→        if (cfg->adc_pattern[i].unit == ADC_UNIT_1) {
   213→            adc_ll_digi_set_pattern_table(ADC_UNIT_1, adc1_pattern_idx, cfg->adc_pattern[i]);
   214→            adc1_pattern_idx++;
   215→        } else if (cfg->adc_pattern[i].unit == ADC_UNIT_2) {
   216→            adc_ll_digi_set_pattern_table(ADC_UNIT_2, adc2_pattern_idx, cfg->adc_pattern[i]);
   217→            adc2_pattern_idx++;
   218→        } else {
   219→            abort();
   220→        }
   221→    }
   222→    adc_ll_digi_set_pattern_table_len(ADC_UNIT_1, adc1_pattern_idx);
   223→    adc_ll_digi_set_pattern_table_len(ADC_UNIT_2, adc2_pattern_idx);
   224→
   225→#endif
   226→
   227→    adc_ll_digi_convert_limit_enable(ADC_LL_DEFAULT_CONV_LIMIT_EN);
   228→    adc_ll_digi_set_convert_limit_num(ADC_LL_DEFAULT_CONV_LIMIT_NUM);
   229→    adc_ll_digi_set_convert_mode(get_convert_mode(cfg->conv_mode));
   230→
   231→    //clock and sample frequency
   232→    adc_hal_digi_sample_freq_config(hal, cfg->clk_src, cfg->clk_src_freq_hz, cfg->sample_freq_hz);
   233→}
   234→
   235→static void adc_hal_digi_dma_link_descriptors(dma_descriptor_t *desc, uint8_t *data_buf, uint32_t per_eof_size, uint32_t eof_step, uint32_t eof_num)
   236→{
   237→    HAL_ASSERT(((uint32_t)data_buf % 4) == 0);
   238→    HAL_ASSERT((per_eof_size % 4) == 0);
   239→    uint32_t n = 0;
   240→    dma_descriptor_t *desc_head = desc;
   241→
   242→    while (eof_num--) {
   243→        uint32_t eof_size = per_eof_size;
   244→
   245→        for (int i = 0; i < eof_step; i++) {
   246→            uint32_t this_len = eof_size;
   247→            if (this_len > DMA_DESCRIPTOR_BUFFER_MAX_SIZE_4B_ALIGNED) {
   248→                this_len = DMA_DESCRIPTOR_BUFFER_MAX_SIZE_4B_ALIGNED;
   249→            }
   250→
   251→            desc[n] = (dma_descriptor_t) {
   252→                .dw0.size = this_len,
   253→                .dw0.length = 0,
   254→                .dw0.suc_eof = 0,
   255→                .dw0.owner = 1,
   256→                .buffer = data_buf,
   257→                .next = &desc[n+1]
   258→            };
   259→            eof_size -= this_len;
   260→            data_buf += this_len;
   261→            n++;
   262→        }
   263→    }
   264→    desc[n-1].next = desc_head;
   265→}
