   267→void adc_hal_digi_start(adc_hal_dma_ctx_t *hal, uint8_t *data_buf)
   268→{
   269→    //stop peripheral and DMA
   270→    adc_hal_digi_stop(hal);
   271→
   272→#if !SOC_GDMA_SUPPORTED
   273→    //reset DMA
   274→    adc_dma_ll_rx_reset_channel(hal->dev, hal->dma_chan);
   275→#endif /* !SOC_GDMA_SUPPORTED */
   276→    //reset peripheral
   277→    adc_ll_digi_reset(hal->dev);
   278→
   279→    //reset the current descriptor address
   280→    hal->cur_desc_ptr = &hal->desc_dummy_head;
   281→    adc_hal_digi_dma_link_descriptors(hal->rx_desc, data_buf, hal->eof_num * SOC_ADC_DIGI_DATA_BYTES_PER_CONV, hal->eof_step, hal->eof_desc_num);
   282→
   283→#if !SOC_GDMA_SUPPORTED
   284→    //start DMA
   285→    adc_dma_ll_rx_start(hal->dev, hal->dma_chan, (lldesc_t *)hal->rx_desc);
   286→#endif /* !SOC_GDMA_SUPPORTED */
   287→    //connect DMA and peripheral
   288→    adc_ll_digi_dma_enable();
   289→    //start ADC
   290→    adc_ll_digi_trigger_enable(hal->dev);
   291→}
