   305→adc_hal_dma_desc_status_t adc_hal_get_reading_result(adc_hal_dma_ctx_t *hal, const intptr_t eof_desc_addr, uint8_t **buffer, uint32_t *len)
   306→{
   307→    HAL_ASSERT(hal->cur_desc_ptr);
   308→
   309→    if (!hal->cur_desc_ptr->next) {
   310→        return ADC_HAL_DMA_DESC_NULL;
   311→    }
   312→
   313→    if ((intptr_t)hal->cur_desc_ptr == eof_desc_addr) {
   314→        return ADC_HAL_DMA_DESC_WAITING;
   315→    }
   316→
   317→    uint8_t *buffer_start = NULL;
   318→    uint32_t eof_len = 0;
   319→    dma_descriptor_t *eof_desc = hal->cur_desc_ptr;
   320→
   321→    //Find the eof list start
   322→    eof_desc = eof_desc->next;
   323→    eof_desc->dw0.owner = 1;
   324→    buffer_start = eof_desc->buffer;
   325→    eof_len += eof_desc->dw0.length;
   326→    if ((intptr_t)eof_desc == eof_desc_addr) {
   327→        goto valid;
   328→    }
   329→
   330→    //Find the eof list end
   331→    for (int i = 1; i < hal->eof_step; i++) {
   332→        eof_desc = eof_desc->next;
   333→        eof_desc->dw0.owner = 1;
   334→        eof_len += eof_desc->dw0.length;
   335→        if ((intptr_t)eof_desc == eof_desc_addr) {
   336→            goto valid;
   337→        }
   338→    }
   339→
   340→valid:
   341→    hal->cur_desc_ptr = eof_desc;
   342→    *buffer = buffer_start;
   343→    *len = eof_len;
   344→
   345→    return ADC_HAL_DMA_DESC_VALID;
   346→}
