    46→/* Convert zephyr,gain property to the ESP32 attenuation */
    47→static inline int gain_to_atten(enum adc_gain gain, adc_atten_t *atten)
    48→{
    49→	switch (gain) {
    50→	case ADC_GAIN_1:
    51→		*atten = ADC_ATTEN_DB_0;
    52→		break;
    53→	case ADC_GAIN_4_5:
    54→		*atten = ADC_ATTEN_DB_2_5;
    55→		break;
    56→	case ADC_GAIN_1_2:
    57→		*atten = ADC_ATTEN_DB_6;
    58→		break;
    59→	case ADC_GAIN_1_4:
    60→		*atten = ADC_ATTEN_DB_12;
    61→		break;
    62→	default:
    63→		return -ENOTSUP;
    64→	}
    65→	return 0;
    66→}
    67→
    68→#ifndef CONFIG_ADC_ESP32_DMA
    69→
    70→/* Convert voltage by inverted attenuation to support zephyr gain values */
    71→static void atten_to_gain(adc_atten_t atten, uint32_t *val_mv)
    72→{
    73→	uint32_t num, den;
    74→
    75→	if (!val_mv) {
    76→		return;
    77→	}
    78→
    79→	switch (atten) {
    80→	case ADC_ATTEN_DB_2_5: /* 1/ADC_GAIN_4_5 */
    81→		num = 4;
    82→		den = 5;
    83→		break;
    84→	case ADC_ATTEN_DB_6: /* 1/ADC_GAIN_1_2 */
    85→		num = 1;
    86→		den = 2;
    87→		break;
    88→	case ADC_ATTEN_DB_12: /* 1/ADC_GAIN_1_4 */
    89→		num = 1;
    90→		den = 4;
    91→		break;
    92→	case ADC_ATTEN_DB_0: /* 1/ADC_GAIN_1 */
    93→	default:
    94→		num = 1;
    95→		den = 1;
    96→		break;
    97→	}
    98→
    99→	*val_mv = (*val_mv * num) / den;
   100→}
