   104→static int adc_esp32_read(const struct device *dev, const struct adc_sequence *seq)
   105→{
   106→	struct adc_esp32_data *data = dev->data;
   107→
   108→	uint8_t channel_id = find_lsb_set(seq->channels) - 1;
   109→
   110→	if (seq->buffer_size < 2) {
   111→		LOG_ERR("Sequence buffer space too low '%d'", seq->buffer_size);
   112→		return -ENOMEM;
   113→	}
   114→
   115→#ifndef CONFIG_ADC_ESP32_DMA
   116→	if (seq->channels > BIT(channel_id)) {
   117→		LOG_ERR("Multi-channel readings not supported");
   118→		return -ENOTSUP;
   119→	}
   120→
   121→	if (seq->options && seq->options->extra_samplings) {
   122→		LOG_ERR("Extra samplings not supported");
   123→		return -ENOTSUP;
   124→	}
   125→
   126→	if (seq->options && seq->options->interval_us) {
   127→		LOG_ERR("Interval between samplings not supported");
   128→		return -ENOTSUP;
   129→	}
   130→#endif /* CONFIG_ADC_ESP32_DMA */
   131→
   132→	if (!VALID_RESOLUTION(seq->resolution)) {
   133→		LOG_ERR("unsupported resolution (%d)", seq->resolution);
   134→		return -ENOTSUP;
   135→	}
   136→
   137→	if (seq->calibrate) {
   138→		/* TODO: Does this mean actual Vref measurement on selected GPIO ?*/
   139→		LOG_ERR("calibration is not supported");
   140→		return -ENOTSUP;
   141→	}
   142→
   143→	data->resolution[channel_id] = seq->resolution;
   144→
   145→#ifdef CONFIG_ADC_ESP32_DMA
   146→	int err = adc_esp32_dma_read(dev, seq);
   147→
   148→	if (err < 0) {
   149→		return err;
   150→	}
   151→#else
   152→	uint32_t acq_raw;
   153→
   154→	if (seq->channels > BIT(channel_id)) {
   155→		LOG_ERR("Multi-channel readings not supported");
   156→		return -ENOTSUP;
   157→	}
   158→
   159→	if (seq->options && seq->options->extra_samplings) {
   160→		LOG_ERR("Extra samplings not supported");
   161→		return -ENOTSUP;
   162→	}
   163→
   164→	if (seq->options && seq->options->interval_us) {
   165→		LOG_ERR("Interval between samplings not supported");
   166→		return -ENOTSUP;
   167→	}
   168→
   169→	adc_oneshot_hal_setup(&data->hal, channel_id);
   170→
   171→#if SOC_ADC_CALIBRATION_V1_SUPPORTED
   172→	adc_set_hw_calibration_code(data->hal.unit, data->attenuation[channel_id]);
   173→#endif /* SOC_ADC_CALIBRATION_V1_SUPPORTED */
   174→
   175→	adc_oneshot_hal_convert(&data->hal, &acq_raw);
   176→
   177→	if (data->cal_handle[channel_id]) {
   178→		if (data->meas_ref_internal > 0) {
   179→			uint32_t acq_mv;
   180→
   181→			adc_cali_raw_to_voltage(data->cal_handle[channel_id], acq_raw, &acq_mv);
   182→
   183→			LOG_DBG("ADC acquisition [unit: %u, chan: %u, acq_raw: %u, acq_mv: %u]",
   184→				data->hal.unit, channel_id, acq_raw, acq_mv);
   185→
   186→#if CONFIG_SOC_SERIES_ESP32
   187→			if (data->attenuation[channel_id] == ADC_ATTEN_DB_12 &&
   188→			    acq_mv > ADC_CLIP_MVOLT_12DB) {
   189→				acq_mv = ADC_CLIP_MVOLT_12DB;
   190→			}
   191→#endif /* CONFIG_SOC_SERIES_ESP32 */
   192→
   193→			/* Fit according to selected attenuation */
   194→			atten_to_gain(data->attenuation[channel_id], &acq_mv);
   195→			acq_raw = acq_mv * ((1 << data->resolution[channel_id]) - 1) /
   196→				  data->meas_ref_internal;
   197→		} else {
   198→			LOG_WRN("ADC reading is uncompensated");
   199→		}
   200→	} else {
   201→		LOG_WRN("ADC reading is uncompensated");
   202→	}
   203→
   204→	/* Store result */
   205→	data->buffer = (uint16_t *)seq->buffer;
   206→	data->buffer[0] = acq_raw;
   207→#endif /* CONFIG_ADC_ESP32_DMA */
   208→
   209→	return 0;
   210→}
