   344→static int adc_esp32_init(const struct device *dev)
   345→{
   346→	struct adc_esp32_data *data = (struct adc_esp32_data *)dev->data;
   347→	const struct adc_esp32_conf *conf = (struct adc_esp32_conf *)dev->config;
   348→	uint32_t clock_src_hz;
   349→
   350→
   351→#if SOC_ADC_DIG_CTRL_SUPPORTED && (!SOC_ADC_RTC_CTRL_SUPPORTED || CONFIG_ADC_ESP32_DMA)
   352→	if (!device_is_ready(conf->clock_dev)) {
   353→		return -ENODEV;
   354→	}
   355→
   356→	clock_control_on(conf->clock_dev, conf->clock_subsys);
   357→#endif
   358→
   359→	esp_clk_tree_src_get_freq_hz(ADC_DIGI_CLK_SRC_DEFAULT,
   360→				     ESP_CLK_TREE_SRC_FREQ_PRECISION_CACHED, &clock_src_hz);
   361→
   362→	if (!device_is_ready(conf->gpio_port)) {
   363→		LOG_ERR("gpio0 port not ready");
   364→		return -ENODEV;
   365→	}
   366→
   367→#ifdef CONFIG_ADC_ESP32_DMA
   368→	int err = adc_esp32_dma_init(dev);
   369→
   370→	if (err < 0) {
   371→		return err;
   372→	}
   373→#else
   374→	adc_oneshot_hal_cfg_t config = {
   375→		.unit = conf->unit,
   376→		.work_mode = ADC_HAL_SINGLE_READ_MODE,
   377→		.clk_src = ADC_DIGI_CLK_SRC_DEFAULT,
   378→		.clk_src_freq_hz = clock_src_hz,
   379→	};
   380→
   381→	adc_oneshot_hal_init(&data->hal, &config);
   382→
   383→	sar_periph_ctrl_adc_oneshot_power_acquire();
   384→#endif /* CONFIG_ADC_ESP32_DMA */
   385→
   386→	for (uint8_t i = 0; i < SOC_ADC_MAX_CHANNEL_NUM; i++) {
   387→		data->resolution[i] = ADC_RESOLUTION_MAX;
   388→		data->attenuation[i] = ADC_ATTEN_DB_0;
   389→		data->cal_handle[i] = NULL;
   390→	}
   391→
   392→	/* Default reference voltage. This could be calibrated externaly */
   393→	data->meas_ref_internal = ADC_ESP32_DEFAULT_VREF_INTERNAL;
   394→
   395→	adc_hw_calibration(conf->unit);
   396→
   397→	return 0;
   398→}
