    41→static void IRAM_ATTR adc_esp32_dma_conv_done(const struct device *dma_dev, void *user_data,
    42→					      uint32_t channel, int status)
    43→{
    44→	ARG_UNUSED(dma_dev);
    45→	ARG_UNUSED(status);
    46→
    47→	const struct device *dev = user_data;
    48→	struct adc_esp32_data *data = dev->data;
    49→
    50→	k_sem_give(&data->dma_conv_wait_lock);
    51→}
