    53→static int adc_esp32_dma_start(const struct device *dev, uint8_t *buf, size_t len)
    54→{
    55→	const struct adc_esp32_conf *conf = dev->config;
    56→	int err;
    57→
    58→	struct dma_config dma_cfg = {0};
    59→	struct dma_status dma_status = {0};
    60→	struct dma_block_config dma_blk = {0};
    61→
    62→	err = dma_get_status(conf->dma_dev, conf->dma_channel, &dma_status);
    63→	if (err) {
    64→		LOG_ERR("Unable to get dma channel[%u] status (%d)",
    65→			(unsigned int)conf->dma_channel, err);
    66→		return -EINVAL;
    67→	}
    68→
    69→	if (dma_status.busy) {
    70→		LOG_ERR("dma channel[%u] is busy!", (unsigned int)conf->dma_channel);
    71→		return -EBUSY;
    72→	}
    73→
    74→	dma_cfg.channel_direction = PERIPHERAL_TO_MEMORY;
    75→	dma_cfg.dma_callback = adc_esp32_dma_conv_done;
    76→	dma_cfg.user_data = (void *)dev;
    77→	dma_cfg.dma_slot = ESP_GDMA_TRIG_PERIPH_ADC0;
    78→	dma_cfg.block_count = 1;
    79→	dma_cfg.head_block = &dma_blk;
    80→	dma_blk.block_size = len;
    81→	dma_blk.dest_address = (uint32_t)buf;
    82→
    83→	err = dma_config(conf->dma_dev, conf->dma_channel, &dma_cfg);
    84→	if (err) {
    85→		LOG_ERR("Error configuring dma (%d)", err);
    86→		return err;
    87→	}
    88→
    89→	err = dma_start(conf->dma_dev, conf->dma_channel);
    90→	if (err) {
    91→		LOG_ERR("Error starting dma (%d)", err);
    92→		return err;
    93→	}
    94→
    95→	return 0;
    96→}
