   131→static int adc_esp32_fill_digi_ctrlr_cfg(const struct device *dev, const struct adc_sequence *seq,
   132→					 uint32_t sample_freq_hz,
   133→					 adc_digi_pattern_config_t *pattern_config,
   134→					 adc_hal_digi_ctrlr_cfg_t *adc_hal_digi_ctrlr_cfg,
   135→					 uint32_t *pattern_len, uint32_t *unit_attenuation)
   136→{
   137→	const struct adc_esp32_conf *conf = dev->config;
   138→	struct adc_esp32_data *data = dev->data;
   139→
   140→	adc_digi_pattern_config_t *adc_digi_pattern_config = pattern_config;
   141→	uint32_t channel_mask = 1, channels_copy = seq->channels;
   142→
   143→	*pattern_len = 0;
   144→	*unit_attenuation = UNIT_ATTEN_UNINIT;
   145→	for (uint8_t channel_id = 0; channel_id < conf->channel_count; channel_id++) {
   146→		if (channels_copy & channel_mask) {
   147→			if (*unit_attenuation == UNIT_ATTEN_UNINIT) {
   148→				*unit_attenuation = data->attenuation[channel_id];
   149→			}
   150→
   151→			if (*unit_attenuation != data->attenuation[channel_id]) {
   152→				LOG_ERR("Channel[%u] attenuation different of unit[%u] attenuation",
   153→					(unsigned int)channel_id, (unsigned int)conf->unit);
   154→				return -EINVAL;
   155→			}
   156→
   157→			adc_digi_pattern_config->atten = data->attenuation[channel_id];
   158→			adc_digi_pattern_config->channel = channel_id;
   159→			adc_digi_pattern_config->unit = conf->unit;
   160→			adc_digi_pattern_config->bit_width = seq->resolution;
   161→			adc_digi_pattern_config++;
   162→
   163→			*pattern_len += 1;
   164→			if (*pattern_len > SOC_ADC_PATT_LEN_MAX) {
   165→				LOG_ERR("Max pattern len is %d", SOC_ADC_PATT_LEN_MAX);
   166→				return -EINVAL;
   167→			}
   168→
   169→			channels_copy &= ~channel_mask;
   170→			if (!channels_copy) {
   171→				break;
   172→			}
   173→		}
   174→		channel_mask <<= 1;
   175→	}
   176→
   177→	soc_module_clk_t clk_src = ADC_DIGI_CLK_SRC_DEFAULT;
   178→	uint32_t clk_src_freq_hz = 0;
   179→
   180→	int err = esp_clk_tree_src_get_freq_hz(clk_src, ESP_CLK_TREE_SRC_FREQ_PRECISION_CACHED,
   181→					       &clk_src_freq_hz);
   182→	if (err != ESP_OK) {
   183→		return -EIO;
   184→	}
   185→
   186→	adc_hal_digi_ctrlr_cfg->conv_mode =
   187→		(conf->unit == ADC_UNIT_1) ? ADC_CONV_SINGLE_UNIT_1 : ADC_CONV_SINGLE_UNIT_2;
   188→	adc_hal_digi_ctrlr_cfg->clk_src = clk_src;
   189→	adc_hal_digi_ctrlr_cfg->clk_src_freq_hz = clk_src_freq_hz;
   190→	adc_hal_digi_ctrlr_cfg->sample_freq_hz = sample_freq_hz;
   191→	adc_hal_digi_ctrlr_cfg->adc_pattern = pattern_config;
   192→	adc_hal_digi_ctrlr_cfg->adc_pattern_len = *pattern_len;
   193→
   194→	return 0;
   195→}
