   197→static void adc_esp32_digi_start(const struct device *dev,
   198→				 adc_hal_digi_ctrlr_cfg_t *adc_hal_digi_ctrlr_cfg,
   199→				 uint32_t number_of_adc_samples, uint32_t unit_attenuation)
   200→{
   201→	const struct adc_esp32_conf *conf = dev->config;
   202→	struct adc_esp32_data *data = dev->data;
   203→
   204→	periph_module_reset(PERIPH_SARADC_MODULE);
   205→	sar_periph_ctrl_adc_continuous_power_acquire();
   206→	adc_lock_acquire(conf->unit);
   207→
   208→#if SOC_ADC_CALIBRATION_V1_SUPPORTED
   209→	adc_set_hw_calibration_code(conf->unit, unit_attenuation);
   210→#endif /* SOC_ADC_CALIBRATION_V1_SUPPORTED */
   211→
   212→#if SOC_ADC_ARBITER_SUPPORTED
   213→	if (conf->unit == ADC_UNIT_2) {
   214→		adc_arbiter_t config = ADC_ARBITER_CONFIG_DEFAULT();
   215→
   216→		adc_hal_arbiter_config(&config);
   217→	}
   218→#endif /* SOC_ADC_ARBITER_SUPPORTED */
   219→
   220→	adc_hal_dma_config_t adc_hal_dma_config = {
   221→#if defined(CONFIG_SOC_SERIES_ESP32)
   222→		.dev = (void *)I2S_LL_GET_HW(ADC_DMA_I2S_HOST),
   223→		.eof_desc_num = 1,
   224→		.eof_step = 1,
   225→#elif defined(CONFIG_SOC_SERIES_ESP32S2)
   226→		.dev = (void *)SPI_LL_GET_HW(SPI3_HOST),
   227→		.eof_desc_num = 1,
   228→		.eof_step = 1,
   229→#endif /* defined(CONFIG_SOC_SERIES_ESP32) */
   230→		.eof_num = number_of_adc_samples,
   231→	};
   232→
   233→	adc_hal_dma_ctx_config(&data->adc_hal_dma_ctx, &adc_hal_dma_config);
   234→	adc_hal_set_controller(conf->unit, ADC_HAL_CONTINUOUS_READ_MODE);
   235→	adc_hal_digi_init(&data->adc_hal_dma_ctx);
   236→	adc_hal_digi_controller_config(&data->adc_hal_dma_ctx, adc_hal_digi_ctrlr_cfg);
   237→	adc_hal_digi_start(&data->adc_hal_dma_ctx, data->dma_buffer);
   238→}
