   240→static void adc_esp32_digi_stop(const struct device *dev)
   241→{
   242→	const struct adc_esp32_conf *conf = dev->config;
   243→	struct adc_esp32_data *data = dev->data;
   244→
   245→	adc_hal_digi_dis_intr(&data->adc_hal_dma_ctx, ADC_HAL_DMA_INTR_MASK);
   246→	adc_hal_digi_clr_intr(&data->adc_hal_dma_ctx, ADC_HAL_DMA_INTR_MASK);
   247→	adc_hal_digi_stop(&data->adc_hal_dma_ctx);
   248→
   249→#if ADC_LL_WORKAROUND_CLEAR_EOF_COUNTER
   250→	periph_module_reset(PERIPH_SARADC_MODULE);
   251→	adc_ll_digi_dma_clr_eof();
   252→#endif
   253→
   254→	adc_hal_digi_deinit(&data->adc_hal_dma_ctx);
   255→	adc_lock_release(conf->unit);
   256→	sar_periph_ctrl_adc_continuous_power_release();
   257→}
