   259→static void adc_esp32_fill_seq_buffer(const void *seq_buffer, const void *dma_buffer,
   260→				      uint32_t number_of_samples)
   261→{
   262→	uint16_t *sample = (uint16_t *)seq_buffer;
   263→	adc_digi_output_data_t *digi_data = (adc_digi_output_data_t *)dma_buffer;
   264→
   265→	for (uint32_t k = 0; k < number_of_samples; k++) {
   266→#if SOC_GDMA_SUPPORTED
   267→		*sample++ = (uint16_t)(digi_data++)->type2.data;
   268→#else
   269→		*sample++ = (uint16_t)(digi_data++)->type1.data;
   270→#endif /* SOC_GDMA_SUPPORTED */
   271→	}
   272→}
