   274→static int adc_esp32_wait_for_dma_conv_done(const struct device *dev)
   275→{
   276→	struct adc_esp32_data *data = dev->data;
   277→	int err = 0;
   278→
   279→	err = k_sem_take(&data->dma_conv_wait_lock, K_MSEC(ADC_DMA_MAX_CONV_DONE_TIME));
   280→	if (err) {
   281→		LOG_ERR("Error taking dma_conv_wait_lock (%d)", err);
   282→	}
   283→
   284→	return err;
   285→}
