   287→int adc_esp32_dma_read(const struct device *dev, const struct adc_sequence *seq)
   288→{
   289→	struct adc_esp32_data *data = dev->data;
   290→	int err = 0;
   291→	uint32_t adc_pattern_len, unit_attenuation;
   292→	adc_hal_digi_ctrlr_cfg_t adc_hal_digi_ctrlr_cfg;
   293→	adc_digi_pattern_config_t adc_digi_pattern_config[SOC_ADC_MAX_CHANNEL_NUM];
   294→
   295→	const struct adc_sequence_options *options = seq->options;
   296→	uint32_t sample_freq_hz = SOC_ADC_SAMPLE_FREQ_THRES_HIGH, number_of_samplings = 1;
   297→
   298→	if (options && options->callback) {
   299→		return -ENOTSUP;
   300→	}
   301→
   302→	if (options && options->interval_us) {
   303→		sample_freq_hz = MHZ(1) / options->interval_us;
   304→		if (sample_freq_hz < SOC_ADC_SAMPLE_FREQ_THRES_LOW ||
   305→		    sample_freq_hz > SOC_ADC_SAMPLE_FREQ_THRES_HIGH) {
   306→			LOG_ERR("ADC sampling frequency out of range: %uHz", sample_freq_hz);
   307→			return -EINVAL;
   308→		}
   309→	}
   310→
   311→	err = adc_esp32_fill_digi_ctrlr_cfg(dev, seq, sample_freq_hz, adc_digi_pattern_config,
   312→					    &adc_hal_digi_ctrlr_cfg, &adc_pattern_len,
   313→					    &unit_attenuation);
   314→	if (err || adc_pattern_len == 0) {
   315→		return -EINVAL;
   316→	}
   317→
   318→	if (options != NULL) {
   319→		number_of_samplings = options->extra_samplings + 1;
   320→	}
   321→
   322→	if (seq->buffer_size < (number_of_samplings * sizeof(uint16_t))) {
   323→		LOG_ERR("buffer size is not enough to store all samples!");
   324→		return -EINVAL;
   325→	}
   326→
   327→	uint32_t number_of_adc_samples = number_of_samplings * adc_pattern_len;
   328→	uint32_t number_of_adc_dma_data_bytes =
   329→		number_of_adc_samples * SOC_ADC_DIGI_DATA_BYTES_PER_CONV;
   330→
   331→	if (number_of_adc_dma_data_bytes > ADC_DMA_BUFFER_SIZE) {
   332→		LOG_ERR("dma buffer size insufficient to store a complete sequence!");
   333→		return -EINVAL;
   334→	}
   335→
   336→#if SOC_GDMA_SUPPORTED
   337→	err = adc_esp32_dma_start(dev, data->dma_buffer, number_of_adc_dma_data_bytes);
   338→#else
   339→	err = esp_intr_enable(data->irq_handle);
   340→#endif /* SOC_GDMA_SUPPORTED */
   341→	if (err) {
   342→		return err;
   343→	}
   344→
   345→	adc_esp32_digi_start(dev, &adc_hal_digi_ctrlr_cfg, number_of_adc_samples, unit_attenuation);
   346→
   347→	err = adc_esp32_wait_for_dma_conv_done(dev);
   348→	if (err) {
   349→		return err;
   350→	}
   351→
   352→	adc_esp32_digi_stop(dev);
   353→
   354→#if SOC_GDMA_SUPPORTED
   355→	err = adc_esp32_dma_stop(dev);
   356→#else
   357→	err = esp_intr_disable(data->irq_handle);
   358→#endif /* SOC_GDMA_SUPPORTED */
   359→	if (err) {
   360→		return err;
   361→	}
   362→
   363→	adc_esp32_fill_seq_buffer(seq->buffer, data->dma_buffer, number_of_adc_samples);
   364→
   365→	return 0;
   366→}
