   381→int adc_esp32_dma_init(const struct device *dev)
   382→{
   383→	struct adc_esp32_data *data = (struct adc_esp32_data *)dev->data;
   384→
   385→	if (k_sem_init(&data->dma_conv_wait_lock, 0, 1)) {
   386→		LOG_ERR("dma_conv_wait_lock initialization failed!");
   387→		return -EINVAL;
